import React,{useEffect,useState} from "react"; import { getModQueue, moderate, exportBook, initTranslations } from "../api";
export default function EditorPanel(){ const [queue,setQueue]=useState<any[]>([]); const [toS3,setToS3]=useState(false); const [title,setTitle]=useState("Сознание как информационная система — Сборник тезисов");
useEffect(()=>{refresh()},[]); const refresh=async()=>setQueue(await getModQueue());
return (<div><h3>Модерация</h3><button onClick={refresh}>Обновить</button><ul>{queue.map(c=>(<li key={c.id} style={{borderBottom:"1px solid #eee",padding:8}}><div><b>Тезис:</b> {c.thesis?.slug}</div><div><b>Автор:</b> {c.author?.email}</div><div style={{whiteSpace:"pre-wrap"}}>{c.textMd}</div><div style={{display:"flex",gap:8,marginTop:8}}><button onClick={async()=>{await moderate(c.id,"APPROVE");refresh();}}>Одобрить</button><button onClick={async()=>{await moderate(c.id,"REJECT");refresh();}}>Отклонить</button></div></li>))}</ul>
<h3>Экспорт</h3><label className="small">Название титула:</label><input value={title} onChange={e=>setTitle(e.target.value)}/>
<label style={{display:"block",marginTop:8}}><input type='checkbox' checked={toS3} onChange={e=>setToS3(e.target.checked)}/> Сохранить в S3 и получить ссылку</label>
<div style={{display:"flex",gap:8,marginTop:8}}><button onClick={async()=>{const res=await exportBook("pdf",{bookSlug:"consciology"},toS3,title); if((res as any)?.url){ window.open((res as any).url,'_blank'); return;} const blob=res as Blob; const u=URL.createObjectURL(blob); const a=document.createElement("a"); a.href=u;a.download="livebook_export.pdf";a.click();URL.revokeObjectURL(u);}}>PDF</button>
<button onClick={async()=>{const res=await exportBook("epub",{bookSlug:"consciology"},toS3,title); if((res as any)?.url){ window.open((res as any).url,'_blank'); return;} const blob=res as Blob; const u=URL.createObjectURL(blob); const a=document.createElement("a"); a.href=u;a.download="livebook_export.epub";a.click();URL.revokeObjectURL(u);}}>ePub</button>
<button onClick={async()=>{const html=await exportBook("html",{bookSlug:"consciology"},false,title) as any; const win=window.open(); win!.document.write(html);}}>HTML</button></div>
<h3>Переводы</h3><button onClick={async()=>{const res=await initTranslations(); alert(JSON.stringify(res));}}>Загрузить базовые переводы</button><p className="small">Перед загрузкой укажите UUID тезиса в <code>backend/prisma/translations_seed.json</code>.</p></div>); }
